import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BTLSZHNB.js";const u=JSON.parse('{"title":"takoform_worker_bundle","description":"Worker Bundle (edge.forms.takoform.com/v1alpha1, role revision).","frontmatter":{"page_title":"takoform_worker_bundle Resource - takoform","subcategory":"Edge Platform Family","description":"Worker Bundle (edge.forms.takoform.com/v1alpha1, role revision)."},"headers":[],"relativePath":"docs/resources/worker_bundle.md","filePath":"docs/resources/worker_bundle.md"}'),i={name:"docs/resources/worker_bundle.md"};function s(d,e,n,c,l,m){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="takoform-worker-bundle" tabindex="-1">takoform_worker_bundle <a class="header-anchor" href="#takoform-worker-bundle" aria-label="Permalink to &quot;takoform_worker_bundle&quot;">​</a></h1><p>Immutable content-addressed module bundle of one worker build, named by the digest of the artifact manifest committed through the content-addressed upload API (decision 0012). The manifest, not this Form, describes the main module and every additional module with its closed media type, exact size, and sha256 digest, so the bundle keeps exactly one source of truth for its bytes. Different bytes commit a different manifest, which is a different bundle.</p><p>This is a <code>revision</code> resource: an immutable snapshot. It is create-only — every desired attribute forces replacement, and rollback means pointing a deployment at an earlier revision, never editing this one.</p><p>This resource speaks the Host API v1alpha3 lane and requires provider v2.1.0 or later (source candidate; not yet published). The configured host selects and operates the concrete backend; no attribute names a vendor, target, credential, price, or implementation. See the <a href="../../examples/resources/takoform_worker_bundle/resource.tf">complete example</a>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, required, forces replacement) — Portable resource name (<code>metadata.name</code>).</li><li><code>manifest_digest</code> (String, optional, computed, forces replacement) — Immutable digest of the committed artifact manifest this bundle is. It is the whole portable desired state: the manifest, not this resource, describes the modules. Declare exactly one of the two authoring modes — reference a manifest already committed to the host by setting this digest, or leave it unset and author the bundle locally with the two arguments below. Writing it alongside local authoring is accepted only when the authored bytes commit exactly that manifest; a disagreement is refused before any host call.</li><li><code>main_module</code> (String, optional, forces replacement) — Local authoring only: relative path of the ES module the runtime instantiates first; it must name one declared module. It is not portable desired state; it describes the artifact manifest the provider commits.</li><li><code>modules</code> (List of Object, optional, forces replacement) — Local authoring only: every module of the bundle. Each entry declares <code>name</code>, <code>content_type</code> (one of the five closed media types), and <code>content_file</code> (a local file path). The provider reads each file, computes its exact <code>size</code> and sha256 <code>digest</code> (both computed attributes), commits the artifact manifest through the content-addressed artifact API, and records the returned <code>manifest_digest</code>. File paths stay in state; file bytes never do. At every plan against existing state the provider re-reads and re-hashes each <code>content_file</code>: changed bytes at an unchanged path change the planned manifest digest and force replacement.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>create_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>30m</code>). There is no <code>update_timeout</code>: this Form declares no update capability. Changing only these provider-side timeouts is applied in place without any host call.</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes; this Form declares no update capability — every desired attribute forces replacement instead.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, or new outputs. Deletes fence on it via <code>If-Match</code>.</li><li><code>ready</code> — true when the closed <code>Ready</code> condition reports <code>True</code>.</li><li><code>outputs_json</code> — JSON-serialized <code>status.outputs</code> document (<code>&quot;{}&quot;</code> when empty).</li><li><code>form_api_version</code>, <code>form_kind</code>, <code>form_definition_version</code>, <code>form_schema_digest</code> — the exact immutable FormRef this state is bound to; reads dispatch on it.</li><li><code>form_package_digest</code> — audit-only package provenance; never part of resource identity, queries, or fences.</li></ul><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_bundle.example NAME</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_bundle.example SPACE/NAME</span></span></code></pre></div><p>An imported bundle restores <code>manifest_digest</code> from the host and leaves <code>main_module</code> and <code>modules</code> null: those are local authoring facts the wire never echoes. The resource is fully manageable afterwards — a configuration that states the same <code>manifest_digest</code> plans empty, and adopting the local files that commit exactly that manifest is not a change either, because the bundle&#39;s identity is the digest.</p>`,11)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
